'use strict';
// NEW v12.2: reusable prepared cycles. Single draw per frame; no opacity blending/ghost legs.
const walkCycleAssets=new Map();
function walkingSheetFile(file){return file.replace('-v1.png','-walk-v2.png');}
function prepareWalkCycle(img,meta){const sheet=document.createElement('canvas');sheet.width=512;sheet.height=meta.rows*64;const c=sheet.getContext('2d');c.imageSmoothingEnabled=true;for(let row=0;row<meta.rows;row++){const boxes=meta.boxes.slice(row*8,row*8+8),sortedHeights=boxes.map(b=>b[3]-b[1]).sort((a,b)=>a-b),scale=meta.targets[row].height/sortedHeights[4];for(let frame=0;frame<8;frame++){const [x,y,right,bottom]=boxes[frame],width=right-x,height=bottom-y,dx=frame*64+meta.targets[row].headX-(meta.anchors[row*8+frame]-x)*scale,dy=row*64+58-meta.targets[row].height;c.save();c.beginPath();c.rect(frame*64,row*64,64,64);c.clip();const runs=meta.clips?.[row*8+frame];if(runs){c.beginPath();for(let k=0;k<runs.length;k+=3)c.rect(dx+(runs[k+1]-x)*scale,dy+(runs[k]-y)*scale,(runs[k+2]-runs[k+1])*scale,scale+.01);c.clip();}c.drawImage(img,x,y,width,height,dx,dy,width*scale,height*scale);c.restore();}}return sheet;}
for(const [file,metadata] of Object.entries(walkSheetMetadata)){const img=new Image(),asset={ready:false,sheet:null,metadata,img};walkCycleAssets.set(file,asset);img.onload=()=>{try{asset.sheet=prepareWalkCycle(img,metadata);asset.ready=true;}catch(error){console.warn('Không chuẩn bị được chu kỳ đi '+file,error);}};img.onerror=()=>console.warn('Không tải được chu kỳ đi '+file);img.src='assets/animation/'+file;}
const walkRenderState=new WeakMap();
function walkingPose(e){const m=motionFor(e),v=Math.hypot(m.vx,m.vy);let s=walkRenderState.get(e);if(!s){s={walking:v>.18};walkRenderState.set(e,s);}s.walking=s.walking?v>.07:v>.18;const stride=e.kind==='human'?.95:e.species==='rabbit'?.7:e.species==='mammoth'?1.6:1.1;const phase=((m.steps/stride+e.id*.137)%1+1)%1;return{walking:s.walking,frame:Math.floor(phase*8),phase};}
